async function collectCodexCandidates(sinceMs: number, titleMap: Map<string, string>): Promise<CodexCandidate[]> {
  const root = codexSessionsRoot();
  const days = daysSince(sinceMs);

  const perDay = await Promise.all(
    days.map(async ({ y, m, d }): Promise<CodexCandidate[]> => {
      const dayDir = path.join(root, y, m, d);
      let files: string[];
      try {
        files = (await readdir(dayDir)).filter((f) => f.startsWith('rollout-') && f.endsWith('.jsonl'));
      } catch {
        return [];
      }

      const out: CodexCandidate[] = [];
      for (const file of files) {
        const match = file.match(CODEX_ROLLOUT_ID_RE);
        if (!match) continue;
        const sessionId = match[1];
        const filePath = path.join(dayDir, file);
        let mtimeMs: number;
        try {
          mtimeMs = (await stat(filePath)).mtimeMs;
        } catch {
          continue;
        }
        if (mtimeMs < sinceMs) continue;

        const subagentOf = await readCodexSubagentParent(filePath);
        out.push({ sessionId, filePath, mtimeMs, title: titleMap.get(sessionId), subagentOf });
      }
      return out;
    }),
  );

  const all = perDay.flat();
  retainLineage(new Set(all.map((c) => c.filePath)));
  return groupCodexSubagents(all);
}

/**
 * Sub-agent rollouts leave the listing and are counted on their ROOT thread's
 * `childCount` — Codex's equivalent of the Claude `<id>/subagents/` pass. A
 * nested sub-agent (depth 2+) climbs to the first ancestor that is not
 * itself a sub-agent. A sub-agent whose root is not in the window is not
 * shown at all, same rule as a Claude subagent whose parent is outside it.
 */
function groupCodexSubagents(all: CodexCandidate[]): CodexCandidate[] {
  const byId = new Map(all.map((c) => [c.sessionId, c]));
  const roots = all.filter((c) => c.subagentOf === null);
  for (const child of all) {
    if (child.subagentOf === null) continue;
    let parentId: string | null = child.subagentOf;
    // Bounded climb: a lineage cycle in corrupt data cannot loop forever.
    for (let depth = 0; parentId !== null && depth < 16; depth++) {
      const parent = byId.get(parentId);
      if (!parent) break;
      if (parent.subagentOf === null) {
        parent.childCount = (parent.childCount ?? 0) + 1;
        break;
      }
      parentId = parent.subagentOf;
    }
  }
  return roots;
}

