 * Cached in memory for `CACHE_TTL_MS` per `(days, runtime)` combination —
 * `limit` is NOT part of the cache key (every caller in this codebase uses
 * the same default; a caller that deliberately varies `limit` should be
 * aware two calls within the TTL window with the same `(days, runtime)` but
 * different `limit` share one cached pre-slice result). Two concurrent
 * callers on a cold cache share the SAME in-flight scan (constat nº2, revue
 * adversariale) rather than each re-running the full two-phase scan below.
 */
export async function listRecentSessions(
  opts: ListRecentSessionsOptions = {},
): Promise<ListRecentSessionsResult> {
  const days = opts.days ?? DEFAULT_DAYS;
  const limit = opts.limit ?? DEFAULT_LIMIT;
  const runtime = opts.runtime;

  const cacheKey = cacheKeyFor(days, runtime);
  const cached = cacheGet(cacheKey);
  if (cached) return cached;

  const pending = inFlight.get(cacheKey);
  if (pending) return pending;

  const run = (async (): Promise<ListRecentSessionsResult> => {
    const sinceMs = Date.now() - days * 24 * 60 * 60_000;

    // PHASE A — cheap metadata only (mtime-filtered), no bounded content
    // read yet (constat nº2). Codex's title map is built ONCE regardless of
    // how many candidates end up in the window (constat nº3 idiom, shared
    // with `runIngest`) — still cheaper than title/preview per file.
