      runtime === 'codex' ? Promise.resolve<ClaudeCandidate[]>([]) : collectClaudeCandidates(sinceMs),
      runtime === 'claude'
        ? Promise.resolve<CodexCandidate[]>([])
        : buildCodexTitleMap().then((titleMap) => collectCodexCandidates(sinceMs, titleMap)),
    ]);

    // PHASE B — merge, sort by mtime (most recent first), slice to `limit`
    // BEFORE any expensive per-entry content read.
    const all: AnyCandidate[] = [
      ...claudeCandidates.map((c): AnyCandidate => ({ runtime: 'claude', mtimeMs: c.mtimeMs, c })),
      ...codexCandidates.map((c): AnyCandidate => ({ runtime: 'codex', mtimeMs: c.mtimeMs, c })),
    ];
    all.sort((a, b) => b.mtimeMs - a.mtimeMs);
    const total = all.length;
    const truncated = total > limit;
    const sliced = all.slice(0, limit);

    // PHASE C — bounded title/preview/cwd reads, ONLY for the entries that
    // survive the slice above.
    const sessions = await Promise.all(
      sliced.map((entry) =>
        entry.runtime === 'claude' ? enrichClaudeCandidate(entry.c) : enrichCodexCandidate(entry.c),
      ),
    );

    const result: ListRecentSessionsResult = { sessions, total, truncated };
    cacheSet(cacheKey, result);
    return result;
  })();

  inFlight.set(cacheKey, run);
  try {
    return await run;
  } finally {
    inFlight.delete(cacheKey);
  }
}
