 * path segment — independent of whatever `encodeClaudeDirName` does or
 * will ever do.
 */
export function isValidCwdHint(cwd: string): boolean {
  if (!cwd || typeof cwd !== 'string') return false;
  if (cwd.length > MAX_CWD_HINT_LENGTH) return false;
  if (!cwd.startsWith('/')) return false;
